var t=`0357-tafelspitz`;var a=`world-0357`;var s=`AT`;var n=`western-europe`;var o=4;var r=119;var l={en:`Tafelspitz`,ua:`Тафельшпіц`};var m={en:`A traditional Austria dish made with beef brisket, yellow onion, carrot, celeriac. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Австрія. Основні інгредієнти: яловича грудинка, жовта цибуля, морква, корінь селери. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 115 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 115 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:115,i:[[`beef-brisket`,950,`g`],[`water`,1800,`ml`],[`yellow-onion`,180,`g`],[`carrot`,230,`g`],[`celeriac`,220,`g`],[`bay-leaf`,2,`leaf`],[`black-peppercorn`,8,`pcs`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:4,i:[[`horseradish-root`,85,`g`],[`apple`,160,`g`],[`lemon-juice`,20,`ml`],[`table-salt`,null,`to_taste`]]}];var c={slug:t,id:a,country:`AT`,region:n,servings:4,minutes:119,title:l,text:m,steps:g};export{s as country,c as default,a as id,r as minutes,n as region,o as servings,t as slug,g as steps,m as text,l as title};